#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;if(!(cin>>n))return 0;vector<int>a(n);for(int&i:a)cin>>i;int h;cin>>h;vector<int> sh(n);for(int i=n-1;i>=0;i--){int l=2*i+1,r=l+1;sh[i]=(l<n?1+sh[l]:0);if(r<n)sh[i]=max(sh[i],1+sh[r]);}int root=-1;vector<int> st;if(n>1)st.push_back(1);while(!st.empty()){int u=st.back();st.pop_back();if(sh[u]<h){root=u;break;}int r=2*u+2,l=2*u+1;if(r<n)st.push_back(r);if(l<n)st.push_back(l);}if(root<0){cout<<sh[0]<<" 0 0 "<<sh[0]<<endl;return 0;}vector<char> gone(n);int cnt=0;st={root};while(!st.empty()){int u=st.back();st.pop_back();if(u>=n||gone[u])continue;gone[u]=1;cnt++;st.push_back(2*u+1);st.push_back(2*u+2);}int aft=0;for(int i=0;i<n;i++)if(!gone[i])aft=max(aft,31-__builtin_clz((unsigned)(i+1)));cout<<sh[0]<<" "<<cnt<<" "<<a[root]<<" "<<aft<<endl;}